            // 判断偶数长度回文
            l = i;
            r = i + 1;
            while (l >= 0 && r < str.length() && string[l] == string[r]) {
                l--;
                r++;
            }
            result = Math.max(result, r - l - 1);
        }
        return result;
    }
}
~~~

