 </body>
~~~
计算属性的方式实现
~~~html
 <body>
     <div id="root">
         <h2>今天天气很{{info}}</h2>
         <button @click="change">切换天气</button>
         <!-- 另一种写法，绑定事件时，@xxx="yyy"，yyy可以写一些简单的语句 -->
         <!-- <button @click="isHot=!isHot">切换天气</button> -->
     </div>

     <script type="text/javascript">
         const vm = new Vue({
             el: '#root',
             data: {
                 isHot: true
             },
             computed: {
                 info() {
                     return this.isHot ? '炎热' : '凉爽'
